(1, 'GRAPHICS DESIGNER', 'Full-time', 'On-site', 'Closed', '<strong style=\"margin-bottom: 30px\">Job Qualifications</strong>\n<ul>\n  <li>\n    <ol>\n      <li>\n        Fluency in written and spoken English\n        <ul style=\"margin-left: 30px\">\n          <li>&#x2022; Good spelling and grammar</li>\n          <li>&#x2022; Good communication skills</li>\n          <li>&#x2022; Ability to proofread work</li>\n        </ul>\n      </li>\n      <li>\n        Proficiency in Adobe Creative Cloud: InDesign, Illustrator, Photoshop,\n        and Acrobat\n        <ul style=\"margin-left: 30px\">\n          <li>&#x2022; InDesign tabs & tables</li>\n          <li>&#x2022; Master template pages</li>\n          <li>&#x2022; Photo editing</li>\n          <li>&#x2022; Creating fillable forms in Acrobat</li>\n          <li>&#x2022; Creating vector graphics</li>\n          <li>\n            &#x2022; Creating vector graphics from raster images, such as logos\n          </li>\n        </ul>\n      </li>\n      <li>\n        Deep knowledge of pre-press for print\n        <ul style=\"margin-left: 30px\">\n          <li>&#x2022; Differences between RGB, CMYK, Pantone, and HEX</li>\n          <li>&#x2022; Differences between raster and vector graphics</li>\n          <li>&#x2022; Bleed, margins, and safe space</li>\n          <li>&#x2022; Fonts and links</li>\n          <li>&#x2022; Resolution</li>\n          <li>&#x2022; File size and structure</li>\n          <li>&#x2022; Following customer supplied brand guidelines</li>\n          <li>&#x2022; Part of the job is fixing customer supplied artwork</li>\n        </ul>\n      </li>\n      <li>\n        An organized individual\n        <ul style=\"margin-left: 30px\">\n          <li>&#x2022; Detail oriented</li>\n          <li>\n            &#x2022; Learn and adhere to naming conventions and file storage\n          </li>\n          <li>&#x2022; Ability to keep track of time while working</li>\n          <li>&#x2022; Keeping good notes about projects and revisions</li>\n          <li>&#x2022; Must be able to work quickly with accuracy</li>\n          <li>\n            &#x2022; Takes initiative since we will be working opposite hours\n          </li>\n          <li>&#x2022; Is not afraid to ask questions</li>\n        </ul>\n      </li>\n      <li>\n        Solid portfolio with examples of designs for many different types of\n        industries, clients, and projects\n        <ul style=\"margin-left: 30px\">\n          <li>\n            &#x2022; Demonstrated knowledge of graphic design principles and\n            color theory\n          </li>\n          <li>\n            &#x2022; A variety of designs – BC, logos, brochures, posters, trade\n            show backdrops, t-shirts, car wraps, etc.\n          </li>\n        </ul>\n      </li>\n    </ol>\n  </li>\n</ul>\n', 'FaPalette', '[{\"name\":\"Graphic-designs-career.png\",\"id\":\"14YLJNyvMoF1osByIyYLCTlBD_pORhhBp\",\"datetime\":\"2025-03-24 09:32:27\"}]', '', '0000-00-00 00:00:00', '2025-03-24 09:32:18'),
(2, 'ACCOUNTS PAYABLE CLERK', 'Full-time', 'On-site', 'Closed', '<p style=\"margin-bottom: 30px\">\n  Mirza Hadi Baig, a Full Stack Developer and Shopify Developer, shared her\n  insights on why website maintenance is crucial for any business. Let’s dive\n  into those reasons and uncover why consistent website maintenance is a must\n  for any business.\n</p>\n\n<strong>Skills & Competencies</strong>\n<ul style=\"margin-bottom: 30px; margin-left: 30px\">\n  <li>&#x2022; High level of accuracy and attention to detail is essential.</li>\n  <li>\n    &#x2022; Initiative-taker capable of working independently with minimal\n    supervision.\n  </li>\n  <li>\n    &#x2022; Organized with ability to manage multiple priorities to meet\n    deadlines.\n  </li>\n  <li>\n    &#x2022; Effective problem solver and team player who enjoys learning and\n    contributing to team goals.\n  </li>\n  <li>\n    &#x2022; Proficient in relevant computer applications such as MS Office\n    including Excel.\n  </li>\n  <li>&#x2022; Accurate keyboard skills and ability to enter data quickly.</li>\n  <li>&#x2022; Good verbal and written communication skills.</li>\n  <li>&#x2022; Information collection, recording, and management skills.</li>\n</ul>\n\n<strong>Prefered Qualifications</strong>\n<ul style=\"margin-bottom: 30px; margin-left: 30px\">\n  <li>\n    &#x2022; Post secondary education in Bookkeeping, Accounting, or a related\n    field (or the equivalent in experience) Blackbaud knowledge or database\n    experience is an asset Familiarity with nonprofit accounting, GAAP, and\n    grant management Three years experience in Alp and/or bookkeeping Experience\n    with international payments and exchange rates (highly preferred)\n  </li>\n</ul>\n', 'IoMdCalculator', '[{\"name\":\"accounting-associate-300x198.png\",\"id\":\"1252rH3n1m__1OMR_x85JQKRKQllAQgKr\",\"datetime\":\"2025-02-20 12:30:55\"}]', '<strong>Job Overview</strong>\n<p style=\"margin-bottom: 30px\">\n  As the Accounts Payable Clerk , you will be a key member of the team, leading\n  the day-to-day operations of the Accounts Payable function and ensuring\n  accurate recording of Alp, grants, and transfers. In partnership with the\n  Director of Operations, you will serve in a supporting role with a wide\n  variety of accounting responsibilities. In this role, you will handle\n  administrative tasks relating to these areas to ensure effective and efficient\n  operations. You will also handle highly confidential material to be handled in\n  the utmost professional manner.\n</p>', '0000-00-00 00:00:00', '2025-03-20 11:24:47'),
(3, 'DONATIONS ADMINISTRATOR', 'Full-time', 'On-site', 'Closed', '<strong>Skills & Competencies</strong>\n<ul style=\"margin-left: 30px\">\n  <li>\n    <ol>\n      <li>&#x2022; Post-Secondary education preferred.</li>\n      <li>&#x2022; Blackbaud knowledge or database experience is an asset.</li>\n      <li>&#x2022; Problem solving skills are essential.</li>\n      <li>\n        &#x2022; Strong Microsoft Office skills are required with superior\n        proficiency in accuracy.\n      </li>\n      <li>\n        &#x2022; Ability to manage multiple projects in a fast-paced environment\n        is required.\n      </li>\n      <li>\n        &#x2022; Enthusiastic individual with excellent organizational and time\n        management skills.\n      </li>\n      <li>\n        &#x2022; High level of accuracy and attention to detail is essential.\n      </li>\n      <li>\n        &#x2022; Self-starter capable of working independently with minimal\n        supervision.\n      </li>\n      <li>\n        &#x2022; Team player who enjoys learning and contributing to team goals.\n      </li>\n    </ol>\n  </li>\n</ul>\n', 'FaHandHolding', '[{\"name\":\"fbs-ads-Donation_trans-careers.png\",\"id\":\"15JIr0fFuoZjll_WkfK7yYSmhlUDWcRzP\",\"datetime\":\"2025-03-24 09:35:18\"}]', '<strong>Job Overview</strong>\n<p style=\"margin-bottom: 30px\">\n  The Donations Administrator is a key member of the team, leading the\n  day-to-day operations of the Donations function and ensuring accurate and\n  timely recording of various types of gifts (checks, wires, online, etc.). This\n  role is responsible to maintain clean donor data, communicate with donors, and\n  send donor acknowledgements, receipts, and consolidated annual statements. In\n  this role, you will handle administrative tasks relating to these areas to\n  ensure effective and efficient operations. You will also handle highly\n  confidential material to be handled in the utmost professional manner.\n</p>\n', '0000-00-00 00:00:00', '2025-03-24 09:35:16'),
(4, 'QA ENGINEER', 'Full-time', 'On-site', 'Closed', '<strong>Job Qualifications</strong>\n<ul style=\"margin-left: 30px\">\n  <li>\n    <ol>\n      <li>&#x2022; Bachelor’s degree in Computer Science, Information Technology, or a related field, or equivalent experience.</li>\n      <li>&#x2022; Proven experience as a QA Engineer, Test Engineer, or similar role in software testing.</li>\n        <li>&#x2022; Strong knowledge of software QA methodologies, tools, and processes.</li>\n        <li>&#x2022; Proficiency in testing web applications, particularly those built with ReactJS, MySQL and Vite.</li>\n        <li>&#x2022; Experience with PHP and MySQL.</li>\n        <li>&#x2022; Familiarity with agile frameworks and regression testing practices.</li>\n        <li>&#x2022; Experience working with version control systems such as Git.</li>\n        <li>&#x2022; Familiarity with continuous integration and deployment pipelines.</li>\n        <li>&#x2022; Strong communication skills and the ability to work effectively within a collaborative team environment.</li>\n        <li>&#x2022; Detail-oriented with a passion for delivering high-quality software.</li>\n        <li>&#x2022; Experience in testing CRM systems or applications in the financial domain.</li>\n        <li>&#x2022; Experience with performance testing tools.</li>\n        <li>&#x2022; Familiarity with cloud platforms such as Siteground.</li>\n        <li>&#x2022; Experience working in a CPA or finance-related environment.</li>\n        </li>\n    </ol>\n  </li>\n</ul>\n', 'FaCode', '[{\"name\":\"fbs-careers-qa.png\",\"id\":\"1debOQJxotYJOcp_OoKHk6XFif5yO4JlJ\",\"datetime\":\"2025-03-24 09:37:14\"}]', '<strong>Job Overview</strong>\n<p  style=\"margin-bottom: 30px\">\n    We are looking for a talented and detail-oriented QA Engineer to join our agile software development team. You will be responsible for ensuring the quality of a corporate CRM intranet website developed in ReactJS, MySQL and Vite with Python. This role is critical as the application will be used by a CPA firm to manage sensitive financial and client data. As the first dedicated QA professional in our team, you will have the opportunity to define and establish our testing processes, working closely with developers and product owners to ensure software quality.\n</p>', '0000-00-00 00:00:00', '2025-03-24 09:37:12'),
(8, 'Social Media Manager', 'Full-time', 'On-site', 'Ongoing', '<strong>Duties and Responsibilities:</strong>\n\n<ul class=\"mb-2\">\n 	<li>&#x2022;  Design and implement social media strategy to align with business goals</li>\n 	<li>&#x2022; Analyzing the company’s digital marketing plan and social media strategy and identifying strategic weaknesses and making </li>\n 	<li>&#x2022; Setting key performance indicators (KPIs) for social media campaigns, such as targets for a certain number of shares or likes and measuring a campaign’s performance against the KPIs</li>\n 	<li>&#x2022;  Monitor, track, analyse and report on performance on social media platforms using tools such as Google Analytics and Facebook Insights</li>\n 	<li>&#x2022;  Identify consumer trends to help with planning social media campaigns</li>\n 	<li>&#x2022;  Research and evaluate the latest tools and techniques in order to find new and better ways of measuring social media activity</li>\n 	<li>&#x2022;  Optimise content to further encourage community interaction and engagement</li>\n 	<li>&#x2022; Manage and facilitate social media communities by responding to social media posts and developing discussions</li>\n</ul>\n\n<strong>Skills:</strong>\n\n<ul class=\"list-text mb--20\">\n 	<li class=\"mb-2\"><strong>Social media:</strong> The ability to use social media to maintain or build a brand is necessary to be a Social Media Manager . These professionals are expected to regularly post text, video and images that engage the company’s target market, follow online conversations on a company’s social media accounts and solve customer concerns using social media platforms.</li>\n 	<li class=\"mb-2\"><strong>Communication:</strong> Great verbal and written communication skills are essential for this occupation. A Social Media Manager must interact with writers, designers, developers and customers and report to senior management personnel. As good communicators, these professionals must identify social media events such as an interesting hashtag or a sensitive topic and share appropriate content that aligns with the company’s social media strategy.</li>\n 	<li class=\"mb-2\"><strong>Creativity:</strong> Crafting engaging content is an important skill for a Social Media Manager. These professionals must constantly align content with customer trends and market changes to interest and engage people.</li>\n 	<li class=\"mb-2\"><strong>Technology:</strong> Computer skills, skills in using social media platforms and skills in using tools that analyze social media platforms are requirements for this position. A Social Media Manager must use digital technologies to meet the goals of social media campaigns.</li>\n 	<li class=\"mb-2\"><strong>Research:</strong> Skills in learning social media trends, identifying new social media tools and finding real-time online conversations are necessary for this position. Social Media Managers must have an understanding of the trends and techniques of social media as well as the company’s online presence to effectively handle social media marketing.</li>\n 	<li class=\"mb-2\"><strong>Time management:</strong> The skill of organizing tasks to meet deadlines is essential for this professional role. Social Media Managers work according to schedules and must meet marketing and business goals.</li>\n</ul>', 'FaAd', '[{\"name\":\"social_media_manager.png\",\"id\":\"1jbwBKUPgqyxp8lVZhcWH0Nr21B_9jyK-\",\"datetime\":\"2025-03-20 11:29:44\"}]', '<strong>Job Overview</strong>\n<ul class=\"mb-2\">\n 	<li>&#x2022; We are looking for a talented Social media manager to administer our social media accounts. You will be responsible for creating original text and video content, managing posts and responding to followers. You will manage our company image in a cohesive way to achieve our marketing goals.</li>\n 	<li>&#x2022; As a Social media manager, we expect you to be up-to-date with the latest digital technologies and social media trends. You should have excellent communication skills and be able to express our company’s views creatively.</li>\n 	<li>&#x2022; Ultimately, you should be able to handle our social media presence ensuring high levels of web traffic and customer engagement.</li>\n</ul>', '2024-11-27 15:42:27', '2025-03-20 11:29:41'),
(9, 'Bookkeeper', 'Full-time', 'On-site', 'Closed', '<strong>SKILLS & COMPENTENCIES</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n <li>&#x2022; High level of accuracy and attention to detail is essential.</li>\n<li>&#x2022; Initiative-taker capable of working independently with minimal supervision.\n</li>\n<li>&#x2022; Organized with ability to manage multiple priorities to meet deadlines.\n</li>\n<li>&#x2022; \nEffective problem solver and team player who enjoys learning and contributing to team goals.\n</li>\n<li>&#x2022; \nProficient in relevant computer applications such as MS Office including Excel.\n</li>\n<li>&#x2022; \nAccurate keyboard skills and ability to enter data quickly.\n</li>\n<li>&#x2022; \nGood verbal and written communication skills.\n</li>\n<li>&#x2022; \nInformation collection, recording, and management skills.\n</li>\n</ul>\n\n<strongPREFFERED QUALIFICATIONS</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n <li>&#x2022; Post secondary education in Bookkeeping, Accounting, or a related field (or the equivalent in experience)\n</li>\n <li>&#x2022; Blackbaud knowledge or database experience is an asset\n</li>\n<li>&#x2022; Familiarity with nonprofit accounting, GAAP, and grant management\n</li>\n<li>&#x2022; Three years experience in Alp and/or bookkeeping\n</li>\n<li>&#x2022; Experience with international payments and exchange rates (highly preferred)\n</li>\n</ul>', 'FaBook', '[{\"name\":\"fbs-ads-bookkeeper_trans.png\",\"id\":\"1dUaUacbqXpKvXaw3lwAuMiH1k9YBu7I1\",\"datetime\":\"2025-03-20 11:58:49\"}]', '<strong>Job Overview</strong>\n<p class=\"mb-4\">\nAs the bookkeeper, you will be maintaining company’s financial records and ensuring that transactions are accurately recorded and organized. You will handle various tasks related to financial reporting, reconciling accounts, and maintaining financial integrity.\n</p>', '2024-11-28 08:22:06', '2025-03-20 11:58:46'),
(10, 'Accounting Instructor ', 'Full-time', 'On-site', 'Closed', '', 'AiOutlineAccountBook', '[{\"name\":\"fbs-ads-Accounting-instructor.png\",\"id\":\"14uSQbwmTzxtXdFuZ5GvXPAeUywB0JNF_\",\"datetime\":\"2025-03-20 11:59:08\"}]', '<strong>Job Qualifications:</strong>\n<ul style=\"margin-left: 30px\">\n <li>&#x2022; Bachelor’s degree in Accountancy, Financial Management, or relevant field\n</li>\n <li>&#x2022; Experience on accounting procedures such as bank reconciliation, sales registration, payroll, general ledger and financial reports and other accounting related work.\n</li>\n <li>&#x2022; Experience in computer-based bookkeeping like QuickBooks or other financial accounting software programs.\n</li>\n <li>&#x2022; \nAdvanced proficiency with Google Suite, MS Word, MS Excel, and MS PowerPoint.\n</li>\n <li>&#x2022; \nProfessional teaching experience is an advantage\n</li>\n <li>&#x2022; \nWilling to be trained.\n</li>\n</ul>', '2024-11-28 12:32:16', '2025-03-20 11:59:05'),
(11, 'Lead Generation Specialist', 'Full-time', 'On-site', 'Closed', '<strong>Qualifications:</strong>\n<p class=\"mb-4\">\nIf you don’t think you meet all of the criteria below but still are interested in the job, please apply. Nobody checks every box, and we’re looking for someone excited to join the team.\n</p>\n<ul style=\"margin-left: 30px\" classs=\"mb-4\">\n <li>&#x2022; College Graduate with a Bachelor’s Degree</li>\n <li>&#x2022; 1-2 years professional experience in the BPO, shared services, or similar industry\n</li>\n <li>&#x2022; Strong preference for candidates with experience in prospecting and lead generation\n</li>\n <li>&#x2022; Excellent analytical skills: use their professional judgment in interpreting findings\n</li>\n <li>&#x2022; Excellent aptitude for research, navigation, and investigation\n</li>\n <li>&#x2022; Excellent verbal and written communication skills\n</li>\n <li>&#x2022; Good organizational skills and attention to detail\n</li>\n <li>&#x2022; Proficient in G Suite productivity tools, such as Gmail, Drive, Docs, Sheets\n</li>\n</ul>\n\n<strong>Key Responsibilities:</strong>\n<ul style=\"margin-left: 30px\">\n <li>&#x2022; Responsible for going through lists and qualifying leads\n</li>\n <li>&#x2022; Responsible for going through lists and qualifying leads\n</li>\n <li>&#x2022; Locate leads through various online avenues\n</li>\n <li>&#x2022; Collect relevant contact details of target companies using online and offline platforms.\n</li>\n <li>&#x2022; Pre-qualify possible leads based on profile fit and recent business activities\n</li>\n <li>&#x2022; Record accurate and up-to-date contact information on qualified leads\n</li>\n <li>&#x2022; Provide feedback on lead sourcing observations for target markets\n</li>\n <li>&#x2022; Organize information and navigate systems for handover to sales\n</li>\n <li>&#x2022; Build and cultivate prospect relationships by initiating communications and conducting follow-up communications in order to move opportunities through the sales funnel.\n</li>\n <li>&#x2022; Manage data for new and prospective clients within CRM, ensuring all communications are logged, information is accurate and documents are attached\n</li>\n <li>&#x2022; Willing to be trained\n</li>\n</ul>', 'AiOutlineFileAdd', '[{\"name\":\"fbs-ads-lead-gen.png\",\"id\":\"1470wMgIIP4nHsJMsSSXR7kCTIG3j-e-L\",\"datetime\":\"2025-03-20 11:59:26\"}]', '<strong>Job Description</strong>\n<p class=\"mb-4\">\nThe Lead Generation Specialist is responsible for prospecting, qualifying and generating new sales leads to support the Senior Account Managers. We are looking for somebody to work predominantly do data entry type work. This individual will be a highly motivated, self-starter able to identify and develop new business prospects from multiple sources including inbound marketing leads, prospect lists, discovery, and individual research.\n</p>', '2024-11-28 12:42:10', '2025-03-20 11:59:23'),
(12, 'Web Developer', 'Full-time', 'On-site', 'Closed', '<strong>Responsibilities:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n <li>&#x2022; Design and development of cross-platform/browser websites and web applications for internal and external use.\n</li>\n <li>&#x2022; Communication with clientele to review, plan and execute programming tasks.\n</li>\n <li>&#x2022; Communication with hosting and email providers to ensure up time and service status.\n</li>\n <li>&#x2022; Administration and implementation of websites on local, staging and development environments.\n</li>\n <li>&#x2022; Administration of e-mail server in order to ensure accounts are configured and available for clientele.\n</li>\n <li>&#x2022; Annoying the management from time to time, as they need the harassment, or so this description thinks….Gotta keep them on their toes.\n</li>\n <li>&#x2022; Ensuring code is backed up to necessary locations.\n</li>\n <li>&#x2022; Monitoring of client issues via email or internal ticketing system.\n</li>\n</ul>\n\n<strong>Education and Training:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n <li>&#x2022; Bachelor’s degree in computer science, web application development or related field\n</li>\n <li>&#x2022; Experience, professional training and certifications\n</li>\n</ul>\n\n<strong>Requirements:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n <li>&#x2022; Having an understanding of the development workflow\n</li>\n <li>&#x2022; Ability to develop and execute application development\n</li>\n <li>&#x2022; Understanding of programming concepts and languages\n  <ul style=\"margin-left:30px\">\n    <li>- Object-oriented</li>\n    <li>- Procedural</li>\n    <li>- Functional </li>\n  </ul>\n</li>\n <li>&#x2022; Understanding of various programming languages\n     <ul style=\"margin-left:30px\">\n    <li>- Advanced or better: HTML, CSS</li>\n    <li>- Intermediate: PHP, MySQL, JavaScript and its various libraries including jQuery\n     </li>\n    <li>- Additional languages are an added bonus</li>\n  </ul>\n</li>\n <li>&#x2022; Understanding of web technology platforms\n     <ul style=\"margin-left:30px\">\n    <li>- Intermediate: Drupal, Symfony</li>\n    <li>- Additional platforms are an added bonus.</li>\n  </ul>\n</li>\n <li>&#x2022; Understanding of responsive web design which is cross-platform and cross-browser compatible.\n</li>\n <li>&#x2022; Following internal and external coding standards such as those set by Drupal or Symfony.\n</li>\n <li>&#x2022; Understanding of SCM, such as GIT\n</li>\n <li>&#x2022; Familiarity with development software\n   <ul style=\"margin-left:30px\">\n    <li>- Adobe Suite</li>\n    <li>- Aptana/Titanium Studio</li>\n    <li>- All major browsers</li>\n  </ul>\n</li>\n <li>&#x2022; Operating Systems\n   <ul style=\"margin-left:30px\">\n    <li>- Novice: *nix Operating System (CentOS preferred)</li>\n    <li>- Expert: Windows and/or Mac</li>\n  </ul>\n </li>\n <li>&#x2022; Being a team player</li>\n <li>&#x2022; Effectively communicating needs of clients and projects to team as necessary</li>\n <li>&#x2022; Effectively communicating with clients to ensure project success</li>\n <li>&#x2022; Adaptability and the willingness to expand current skill set.\n</li>\n</ul>', 'PiWebhooksLogo', '[{\"name\":\"fbs-ads-web.png\",\"id\":\"1L-cmTj1DUl5Ku7u15SCp6X0cq4AWno8a\",\"datetime\":\"2025-03-20 11:59:39\"}]', '<strongJob Description:/strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n <li>&#x2022; Programming languages for this role are geared towards open source technology such as PHP, MySQL, HTML, CSS, and JavaScript. As technology evolves it is crucial that the basic concepts of object-oriented programming are understood.\n</li>\n <li>&#x2022; Although not required, an understanding of Linux command-line scripting and management is to be considered a bonus. It is important that this individual be a ninja or growing ninja of programming tasks.\n</li>\n <li>&#x2022; This role will be in constant communications with clients and third parties to ensure that all necessary facets are operational and functional. It may be important to understand that you need to be cool and down to Earth. Like a cool cat.\n</li>\n <li>&#x2022; This role is one that requires occasional nights and weekends to ensure application rollouts go well, given internal and external availability.\n</li>\n <li>&#x2022; This individual who requires this role must be a general jack of all trades who is quirky, odd, strange, and an all-around good communicator who is very much outspoken and bold. Very bold. Oh, and placing emphasis on wrong syllables.\n</li>\n <li>&#x2022; A primary key to being successful in this position is having a background in application development while being able to learn, grow and expand as the environment changes\n</li>\n</ul>', '2024-11-28 13:13:05', '2025-03-20 11:59:36'),
(13, 'On-site Virtual Assistant (Office-based)', 'Full-time', 'On-site', 'Closed', '', 'LuMonitor', '[{\"name\":\"hiring-virtual-assistant-career.png\",\"id\":\"1sJur0HRIVYq5wE-LUl95F_udtEXovG5W\",\"datetime\":\"2025-03-24 09:40:39\"}]', '<strong>Key Skills:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n <li>&#x2022; English Proficiency: Can converse and comprehend English well.\n</li>\n <li>&#x2022; Flexibility and Adaptability: Enjoying a variety of work tasks.\n</li>\n <li>&#x2022; Ability to multitask: Able to listen, understand, and type simultaneously.\n</li>\n <li>&#x2022; Good oral and written communication skills\n</li>\n <li>&#x2022; Fast and accurate typing skills\n</li>\n <li>&#x2022; Organized and strong attention to details\n</li>\n <li>&#x2022; Enjoys researching things\n</li>\n <li>&#x2022; Can take initiative on things if they don’t have a checklist\n</li>\n <li>&#x2022; Strong knowledge of standard software packages like Microsoft application (Word, Excel, Powerpoint) and the ability to learn company-specific software if required\n</li>\n <li>&#x2022; Understands technology; Google Drive, (how to interact within G-documents), Google Photos, Youtube, Gmail, Google Calendar, Google Tasks, etc.\n</li>\n</ul>', '2024-11-28 13:27:49', '2025-03-24 09:40:36'),
(14, 'Online Sales Assistant', 'Full-time', 'On-site', 'Closed', '', 'LuShoppingBasket', '[{\"name\":\"fbs-career-sales-assistant.png\",\"id\":\"1ET4ruhYItcWVdsUGx2Hmv4syHIpSA5Dr\",\"datetime\":\"2025-03-20 12:04:00\"}]', '<strong>Job Overview</strong>\n<p>\nWe are looking for a talented and motivated Salesperson who is eager to work from home. You will be responsible for selling our products, so excellent English writing skills are an absolute must. We need someone who is available to start as soon as possible, so don\'t miss this opportunity!\n</p>\n\n<p>\nIn this position you will be the face of our company and must have a professional attitude when dealing with customers. Comfort with working independently is also essential.\n</p>\n\n<p>\nThe ideal candidate should have prior experience in sales and/or customer service and be able to think critically while managing their time efficiently. Experience with email marketing tools is preferred but not required.\n</p>\n\n<p>\nIf you believe you have what it takes, don\'t hesitate to apply!\n</p>\n\n', '2024-11-28 13:36:51', '2025-03-20 12:03:55'),
(15, 'Technical Support Engineer', 'Full-time', 'On-site', 'Closed', '<strong>Responsibilities:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Research and identify solutions to software and hardware issues</li>\n<li>&#x2022; Diagnose and troubleshoot technical issues, including account setup and network configuration</li>\n<li>&#x2022; Ask customers targeted questions to quickly understand the root of the problem</li>\n<li>&#x2022; Track computer system issues through to resolution, within agreed time limits</li>\n<li>&#x2022; Talk clients through a series of actions, either via phone, email or chat, until they’ve solved a technical issue</li>\n<li>&#x2022; Properly escalate unresolved issues to appropriate internal teams (e.g. software developers)</li>\n<li>&#x2022; Provide prompt and accurate feedback to customers</li>\n<li>&#x2022; Refer to internal database or external resources to provide accurate tech solutions</li>\n<li>&#x2022; Ensure all issues are properly logged</li>\n<li>&#x2022; Prioritize and manage several open issues at one time</li>\n<li>&#x2022; Follow up with clients to ensure their IT systems are fully functional after troubleshooting</li>\n<li>&#x2022; Prepare accurate and timely reports</li>\n<li>&#x2022; Document technical knowledge in the form of notes and manuals</li>\n<li>&#x2022; Maintain jovial relationships with clients</li>\n</ul>\n\n<strong>Requirements and Skills:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022;  Proven work experience as a Technical Support Engineer, Desktop Support Engineer, IT Help Desk Technician or similar role</li>\n<li>&#x2022;  Hands-on experience with Windows/Linux/Mac OS environments</li>\n<li>&#x2022;  Good understanding of computer systems, mobile devices and other tech products</li>\n<li>&#x2022;  Ability to diagnose and troubleshoot basic technical issues</li>\n<li>&#x2022;  Familiarity with remote desktop applications and help desk software (eg. Zendesk)</li>\n<li>&#x2022;  Excellent problem-solving and communication skills</li>\n<li>&#x2022;  Ability to provide step-by-step technical help, both written and verbal</li>\n<li>&#x2022; BS degree in Information Technology, Computer Science or relevant field</li>\n<li>&#x2022; Additional certification in Microsoft, Linux, Cisco or similar technologies is a plus</li>\n</ul>', 'AiFillSetting', '[{\"name\":\"fbs-ads-TSE-1-300x189.jpg\",\"id\":\"1d_SwUksr9sIt1SEHdBVk4-1nJ9-84CIs\",\"datetime\":\"2025-03-20 11:56:38\"}]', '<strong>Job Overview</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n <li>&#x2022; We are looking for a competent Technical Support Engineer to provide fast and useful technical assistance on computer systems. You will diagnose and troubleshoot software and hardware problems and help our customers install applications and programs.</li>\n <li>&#x2022; Technical Support Engineer responsibilities include resolving network issues, configuring operating systems and using remote desktop connections to provide immediate support. You will use email and chat applications to give clients quick answers to simple IT issues. For more complex problems that require nuanced instruction, you will contact clients via phone and/or provide clear, written instructions and technical manuals.</li>\n <li>&#x2022; To be qualified for this role, you should hold a degree in a relevant field, like Computer Science, IT or Software Engineering. Microsoft, Cisco, Linux or similar certification is a plus. If you’re naturally a helper, enjoy assisting people with computer issues and are able to explain technical details simply, we’d like to meet you.</li>\n <li>&#x2022; Ultimately, you will be a person our customers trust. They will rely on you to provide timely and accurate solutions to their technical problems.</li>\n</ul>', '2024-11-28 13:43:33', '2025-03-20 11:56:35'),
(16, 'Customer Service Representative', 'Full-time', 'On-site', 'Closed', '<strong>Skills & Qualifications:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Graduate of a 4-year College Course</li>\n<li>&#x2022; With at least 1 year of Customer Service and Call Center experience</li>\n<li>&#x2022; Effective communication skills</li>\n<li>&#x2022; Excellent English skills - must at least be intermediate level</li>\n<li>&#x2022; Strong customer service skills (ability to build rapport, demonstrate empathy, and outline key steps in delivering good customer service)</li>\n<li>&#x2022; Calm under pressure</li>\n<li>&#x2022; Ability to multi-task and navigate multiple applications at the same time</li>\n<li>&#x2022; Capable of working onsite on a graveyard shift (mid-shift)</li>\n<li>&#x2022; Knowledge retention</li>\n<li>&#x2022; Attention to detail</li>\n<li>&#x2022; Organization</li>\n<li>&#x2022; Flexibility</li>\n<li>&#x2022; Friendly</li>\n<li>&#x2022; Ability to work independently and as a team player</li>\n</ul>', 'FaHeadset', '[{\"name\":\"fbsAdsCSR-300x189.png\",\"id\":\"1n2GcFBGYZA4AWGrI8KbJTklL-B5YWk8h\",\"datetime\":\"2025-03-24 09:41:30\"}]', '<strong>Job Description:</strong>\n<p>Do you find joy in helping others and problem solving to make a positive impact? If so, this could be the perfect match!</p>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022;  Communicate with customers on a variety of channels.</li>\n<li>&#x2022; Documents all handled calls accurately.</li>\n<li>&#x2022; Resolving customer issues efficiently and courteously.</li>\n<li>&#x2022; Provide a memorable customer experience and awesome customer service.</li>\n<li>&#x2022; Complete after-call work and other assigned administrative duties efficiently.</li>\n<li>&#x2022; Adhere to the prescribed shift and schedule</li>\n<li>&#x2022; Adhere to set service level targets or key performance indicators</li>\n</ul>', '2024-11-28 14:04:47', '2025-03-24 09:41:25'),
(17, 'Data Entry Operator', 'Full-time', 'On-site', 'Closed', '<strong>Job Description:</strong>\n<p class=\"mb-4\">In charge of entering all the data into different computer databases. In addition, they manage and maintain effective record keeping, organizing files to collect information for future use.</p>\n\n<strong>Responsibilities:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Insert customer and account data by inputting text-based and numerical information from source documents within time limits</li>\n 	<li>&#x2022; Compile, verify the accuracy and sort information according to priorities to prepare source data for computer entry</li>\n 	<li>&#x2022; Review data for deficiencies or errors, correct any incompatibilities if possible, and check the output</li>\n 	<li>&#x2022; Research and obtain further information for incomplete documents</li>\n 	<li>&#x2022; Apply data program techniques and procedures</li>\n 	<li>&#x2022; Generate reports, store completed work in designated locations, and perform backup operations</li>\n        <li>&#x2022; Scan documents and print files, when needed</li>\n        <li>&#x2022; Keep information confidential</li>\n        <li>&#x2022; Respond to queries for information and access relevant files</li>\n        <li>&#x2022; Comply with data integrity and security policies</li>\n        <li>&#x2022; Ensure proper use of office equipment and address any malfunctions</li>\n</ul>\n\n<strong>Requirements and Skills:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Proven data entry work experience, as a Data Entry Operator or Office Clerk</li>\n       <li>&#x2022; Experience with MS Office and data programs</li>\n       <li>&#x2022; Familiarity with administrative duties</li>\n       <li>&#x2022; Experiences using office equipment, like fax machines and scanner</li>\n       <li>&#x2022; Typing speed and accuracy</li>\n       <li>&#x2022; Excellent knowledge of correct spelling, grammar, and punctuation</li>\n       <li>&#x2022; Attention to detail</li>\n       <li>&#x2022; Organization skills, with an ability to stay focused on assigned tasks</li>\n       <li>&#x2022; College graduate; additional computer training or certification will be an asset</li>\n</ul>', 'LuFileSpreadsheet', '[{\"name\":\"data-entry-operator-300x189.png\",\"id\":\"1eUuj71FRRpb3pzYpHq2oov7ID3Kufma3\",\"datetime\":\"2025-03-20 12:03:23\"}]', '', '2024-11-28 14:27:39', '2025-03-20 12:03:20'),
(18, 'Accounting Associate', 'Full-time', 'On-site', 'Ongoing', '<strong>Job Descriptions</strong>\n<p class=\"mb-4\">\nMainly focuses on US-based payroll, sales tax filing, bookkeeping and tax return filing using Cloud-based programs\n</p>\n\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n	<li>&#x2022;  Compile and analyze raw data for basic payroll processing</li>\n 	<li>&#x2022;  General Bookkeeping to Financial Reporting</li>\n 	<li>&#x2022;  Monthly data transaction entry</li>\n 	<li>&#x2022;  Bank Reconciliation</li>\n 	<li>&#x2022;  Prepare Sales Report and sales tax filing</li>\n 	<li>&#x2022; Accounts Receivable and Accounts Payable</li>\n 	<li>&#x2022; Billing and Invoicing</li>\n 	<li>&#x2022; Fixed Assets entry with Depreciation/Amortization Schedule</li>\n</ul>\n\n<strong>Job Qualifications:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Bachelor\'s degree in Accountancy, Financial Management, or relevant field.</li>\n 	<li>&#x2022; Experience on accounting procedures such as bank reconciliation, sales registration, payroll, general ledger and financial reports and other accounting related work.</li>\n 	<li>&#x2022; Experience in computer-based bookkeeping like Quickbooks or other financial accounting software programs.</li>\n 	<li>&#x2022; Advanced proficiency with Google Suite, MS Word, and MS Excel</li>\n 	<li>&#x2022; Work experience in accounting/bookkeeping is an advantage.</li>\n 	<li>&#x2022; Willing to be trained.</li>\n</ul>\n\n<strong>Job Skills:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Proficient in Data Entry skills</li>\n 	<li>&#x2022; Keen attention to detail and has reliable analytical skills</li>\n 	<li>&#x2022; Good communication skills (both written and oral)</li>\n 	<li>&#x2022; Computer literate</li>\n 	<li>&#x2022; Performs such other accounting related functions that may be assigned from time to time.</li>\n</ul>', 'FaCalculator', '[{\"name\":\"accounting-associate-300x198.png\",\"id\":\"1ukKIf6lmyCy1_QtGUB0fqKrqrfC6LRTI\",\"datetime\":\"2025-03-20 11:31:39\"}]', '', '2024-11-28 14:34:28', '2025-03-20 11:31:33'),
(19, 'Senior Service Desk Engineer', 'Full-time', 'On-site', 'Closed', '<strong>Responsibilities:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Responsible for the completion of long-term IT engineering projects on-time, pulling in necessary resources</li>\n 	<li>&#x2022; Implement and update network infrastructure, software, and hardware for new and existing clients</li>\n 	<li>&#x2022; Create and maintain documentation</li>\n 	<li>&#x2022; Provide new technology training to clients</li>\n 	<li>&#x2022; Troubleshoot technical issues as they arrive</li>\n 	<li>&#x2022; Resolve high-level help desk support requests as needed</li>\n 	<li>&#x2022; Engage in internal company projects as needed</li>\n 	<li>&#x2022; Contribute to team effort by accomplishing related results as needed</li>\n 	<li>&#x2022; Maintain safe and clean working environment by enforcing procedures, rules, and regulations</li>\n 	<li>&#x2022; Manage client communication and drive progress for assigned projects</li>\n 	<li>&#x2022; Provide clients with regular updates on project schedule and action items</li>\n 	<li>&#x2022; Work closely with Project Management Team on change of scope</li>\n</ul>\n\n<strong>Qualifications and requirements (or equivalent experience):</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; 7+ years in IT with increasing responsibility</li>\n 	<li>&#x2022; Experience creating and managing a work-breakdown structure</li>\n 	<li>&#x2022; VCP6-DCV (VMware)</li>\n 	<li>&#x2022; CompTIA+ and/or Network+</li>\n 	<li>&#x2022; Extensive experience with Office365 doing email migrations from on-prem exchange</li>\n 	<li>&#x2022; Extensive experience implementing new backup solutions</li>\n 	<li>&#x2022; Virtualization experience</li>\n 	<li>&#x2022; SAN Storage experience</li>\n 	<li>&#x2022; NAS Storage experience</li>\n 	<li>&#x2022; Excellent communication and interpersonal skills</li>\n 	<li>&#x2022; Understands the importance of outstanding customer service</li>\n 	<li>&#x2022; Cool and collected under pressure</li>\n 	<li>&#x2022; Able to multitask efficiently</li>\n</ul>\n\n<strong>Additional Skills (optional):</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022;  ITIL v3 (even if expired)</li>\n 	<li>&#x2022; MCSE (Microsoft)</li>\n 	<li>&#x2022; CISSP</li>\n 	<li>&#x2022; Any other VCP6 or 7</li>\n 	<li>&#x2022; Firewall certifications</li>\n 	<li>&#x2022; Experience with Veeam</li>\n 	<li>&#x2022; Experience with SAN’s</li>\n</ul>', 'FaDesktop', '[{\"name\":\"Senior-Service-Desk-Engineer-300x189.png\",\"id\":\"1faKrfKRab7e3doreasktmpxfwehjDfdL\",\"datetime\":\"2025-03-20 12:05:37\"}]', '<strong>The Role:</strong>\n<p class=\"mb-4\">\nWe are looking for an accountable, proactive Senior Systems Engineer to be responsible for all engineering and technical disciplines required for executing on technical help desk issues.\n</p>\n', '2024-11-28 14:42:04', '2025-03-20 12:05:19'),
(20, 'IT Support Staff', 'Full-time', 'On-site', 'Closed', '', 'TiSupport', '[{\"name\":\"fbs-ads-IT-Supp-300x189.png\",\"id\":\"1iXgPy7E7BBuuLyYSHrw0-Pq8--u0E_i0\",\"datetime\":\"2025-03-20 12:02:53\"}]', '<strong>Qualifications:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Candidate must possess at least Bachelor\'s/College Degree in Computer Science/Information Technology or equivalent.</li>\n 	<li>&#x2022; Preferably Experienced Employee specialized in IT/Computer - Network/System/Database Admin or equivalent.</li>\n 	<li>&#x2022; Maintenance, monitoring, and troubleshooting of computer networks, systems and all other IT related task.</li>\n 	<li>&#x2022; With strong knowledge in computer software programs for document generation.</li>\n 	<li>&#x2022; Management of company’s tools and equipment and property inventory using any database software application.</li>\n 	<li>&#x2022; Provide technical direction to co-workers on computer and network usage and offer comprehensive advice and instructions.</li>\n</ul>', '2024-11-28 14:49:42', '2025-03-20 12:02:50'),
(21, 'Mobile App Developer', 'Full-time', 'On-site', 'Closed', '<strong>Required Skills:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Programming languages such as C#, Java, Objective-C, Swift, Python</li>\n 	<li>&#x2022; Can program mobile apps on both platforms (Android/iOS)</li>\n 	<li>&#x2022; Experience in developing apps using Xamarin, Android Studio, Xcode</li>\n 	<li>&#x2022; Have a good sense of utilizing mobile UI/UX design</li>\n 	<li>&#x2022; The ability to learn quickly and follow technical plans</li>\n 	<li>&#x2022; Problem-solving skills</li>\n 	<li>&#x2022; Strong communication skills</li>\n 	<li>&#x2022; Bachelor\'s degree in any IT related course</li>\n</ul>', 'FaMobile', '[{\"name\":\"hiring-mobile-dev-300x198.png\",\"id\":\"1yIxglEhuHZdxZVYrmlswa7zBU1BvdFzF\",\"datetime\":\"2025-03-24 09:43:38\"}]', '<strong>Responsibilities:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Create, maintain and implement the source code to develop mobile apps and programs that meet the needs and requirements of the clients</li>\n 	<li>&#x2022; Discussing the client\'s requirements and proposed solutions with the team</li>\n 	<li>&#x2022; Developing application programming interfaces (APIs) for mobile apps</li>\n 	<li>&#x2022; Keeping up to date with the terminology, concepts, and best practices</li>\n 	<li>&#x2022; Using and adapting to existing web applications for apps</li>\n 	<li>&#x2022; Working closely with the team to innovate app functionality and design</li>\n</ul>', '2024-11-28 14:55:51', '2025-03-24 09:43:33'),
(22, 'WordPress Developer', 'Full-time', 'On-site', 'Closed', '<strong>Required Skills:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Exceptional writing, communication, and organizational skills</li>\n 	<li>&#x2022; Knowledge of HTML, CSS, JavaScript, PHP &amp; MySQL Database and experience with WordPress</li>\n 	<li>&#x2022; Ability to manage multiple projects in a fast-paced, deadline-driven environment</li>\n 	<li>&#x2022; Basic Adobe Photoshop skills</li>\n 	<li>&#x2022; Proven ability to build consensus and work effectively within a cross-departmental team</li>\n 	<li>&#x2022; Bachelor\'s degree in any IT related course</li>\n</ul>', 'FaCode', '[{\"name\":\"hiring-wordpress-300x198.png\",\"id\":\"1AcvneuHvmqV1GMZYEl0GnrZ8tRQ-ucKy\",\"datetime\":\"2025-03-24 09:44:46\"}]', '<strong>Responsibilities:</strong>\n<ul style=\"margin-left: 30px\" class=\"mb-4\">\n<li>&#x2022; Create, develop and manage content for the organization\'s web presence</li>\n 	<li>&#x2022; Maintain a consistent look and feel throughout all web properties</li>\n 	<li>&#x2022; Proofread all web content and ensure accuracy of data</li>\n 	<li>&#x2022; Assure web-based information is archived for future needs and reference</li>\n 	<li>&#x2022; Track and report on relevant site metrics</li>\n 	<li>&#x2022; Work cooperatively with key team members, clients, and vendors</li>\n</ul>', '2024-11-28 15:01:30', '2025-03-24 09:46:13'),
(25, 'Executive Assistant', 'Full-time', 'On-site', 'Ongoing', '<strong>Required Skills:</strong>\n<ul class=\"mb-2\">\n 	<li>&#x2022; Proficiency with task management tools (ClickUp, Asana, Trello, etc.)\n    </li>\n 	<li>&#x2022; Expertise in Google Suite (Gmail, Google Calendar, Google Drive)\n    </li>\n 	<li>&#x2022; Excellent communication and organizational skills\n    </li>\n 	<li>&#x2022; Ability to manage multiple tasks efficiently and meet deadlines\n    </li>\n</ul>\n\n<strong>Preferred Skills:</strong>\n<ul class=\"mb-2\">\n 	<li>&#x2022; Experience with GoHighLevel CRM or similar platforms\n    </li>\n 	<li>&#x2022; Familiarity with AI tools (e.g., ChatGPT) for task automation and customer support\n    </li>\n</ul>\n\n<strong>Experience Level:</strong>\n<ul class=\"mb-2\">\n 	<li>&#x2022; 1-2 years of relevant experience\n    </li>\n</ul>\n\n<strong>Qualifications:</strong>\n<ul class=\"mb-2\">\n 	<li>&#x2022; College degree (preferred)\n    </li>\n</ul>', 'FaEnvelopeOpenText', '[{\"name\":\"fbs-ads-ea.png\",\"id\":\"1AZwJRX5h2bw7gD_HWclCdCTswB_mg5w5\",\"datetime\":\"2025-03-20 11:28:31\"}]', '<strong>Key Responsibilities:</strong>\n<ul class=\"mb-2\">\n 	<li>&#x2022; <b>Scheduling & Calendar Management: </b> Handle \n          appointment scheduling and ensure efficient calendar management \n           for the team.\n    </li>\n 	<li>&#x2022; <b>Communications: </b> Manage email \n          correspondence and assist with internal and external communications.\n    </li>\n 	<li>&#x2022; <b>Customer Service:</b> Provide exceptional customer \n         service to clients and maintain relationships via phone, email, or chat.\n    </li>\n 	<li>&#x2022; <b>CRM Management:</b> Manage customer relationship \n         management (CRM) tools, track leads, and ensure accurate data \n         entry.\n    </li>\n    <li>&#x2022; <b>Sales & Marketing Platform Management:</b> Support \n        sales and marketing by managing related platforms and tools.\n    </li>\n</ul>', '2025-03-20 11:28:28', '2025-03-20 11:28:28');

